func fix(q: LinkedList<Int64>, cursor: ?LinkedListNode<Int64>, t: Int64): Int64 {
    if (t <= 0) {
        return 0
    }
    let start = match (cursor) {
        case Some(node) => node
        case None => return 0
    }
    var sum: Int64 = 0
    var weight: Int64 = 1
    var count: Int64 = 0
    var it = q.backward(start)
    while (count < t) {
        match (it.next()) {
            case Some(v) =>
                sum += v * weight
                weight += 1
                count += 1
            case None => break
        }
    }
    return sum
}

main() {
    let q0 = LinkedList<Int64>([8, 3, 6, 1])
    let r0 = fix(q0, q0.nodeAt(1), 2)
    println(r0 == 8 && q0.toArray() == [8, 3, 6, 1])
    let q1 = LinkedList<Int64>([5, 5, -3, 9])
    let r1 = fix(q1, q1.nodeAt(2), 3)
    println(r1 == 15 && q1.toArray() == [5, 5, -3, 9])
}

