func fix(q: LinkedList<Int64>, cursor: ?LinkedListNode<Int64>, t: Int64): Int64 {
    if (q.isEmpty()) {
        return -81
    }
    match (cursor) {
        case Some(node) =>
            let next = q.forward(node).iterator()
            match (next.next()) {
                case Some(v) =>
                    let old = v
                    let newVal = old + t
                    q.remove(nextNode(q, node))
                    q.addAfter(node, newVal)
                    return old
                case None => return -81
            }
        case None => return -81
    }
}

func nextNode(q: LinkedList<Int64>, node: LinkedListNode<Int64>): LinkedListNode<Int64> {
    let it = q.forward(node).iterator()
    it.next()
    match (it.next()) {
        case Some(_) =>
            // 需要获取节点本身，使用 nodeAt 定位
            let idx = indexOfNode(q, node)
            match (q.nodeAt(idx + 1)) {
                case Some(n) => return n
                case None => return node
            }
        case None => return node
    }
}

