    var i = 0
    var it = q.iterator()
    while (true) {
        match (it.next()) {
            case Some(_) =>
                match (q.nodeAt(i)) {
                    case Some(n) =>
                        if (n == node) {
                            return i
                        }
                    case None => return -1
                }
                i++
            case None => return -1
        }
    }
    return -1
